class Solution { public:vector<vector<int>> constructProductMatrix(vector<vector<int>>& grid){const int MOD=12345;int rows=grid.size(),columns=grid[0].size();vector<vector<int>> answer(rows,vector<int>(columns));long long prefix=1;for(int row=0;row<rows;++row)for(int column=0;column<columns;++column){answer[row][column]=prefix;prefix=prefix*(grid[row][column]%MOD)%MOD;}long long suffix=1;for(int row=rows-1;row>=0;--row)for(int column=columns-1;column>=0;--column){answer[row][column]=answer[row][column]*suffix%MOD;suffix=suffix*(grid[row][column]%MOD)%MOD;}return answer;} };
